`timescale 1ns/1ps

module tb_fft_8pt_8bit;

// Parameters
parameter CLK_PERIOD = 10;

// Signals
reg clk;
reg rst;
reg signed [7:0] x_re;
reg signed [7:0] x_im;
wire signed [7:0] y_re;
wire signed [7:0] y_im;

// Expected outputs for test cases
reg signed [7:0] expected_re [0:7];
reg signed [7:0] expected_im [0:7];

// Error counter and loop variable
integer error_count; // Moved outside initial block
integer i; // Moved outside initial block

// Instantiate DUT
fft_8pt_8bit dut (
    .clk(clk),
    .rst(rst),
    .x_re(x_re),
    .x_im(x_im),
    .y_re(y_re),
    .y_im(y_im)
);

// Clock generation
initial begin
    clk = 0;
    forever #(CLK_PERIOD/2) clk = ~clk;
end

// Test procedure
initial begin
    error_count = 0;

    // Initialize expected outputs for impulse input (1 + j0 at t=0)
    expected_re[0] = 8'sb01111111; // DC component
    expected_re[1] = 8'sb01111111;
    expected_re[2] = 8'sb01111111;
    expected_re[3] = 8'sb01111111;
    expected_re[4] = 8'sb01111111;
    expected_re[5] = 8'sb01111111;
    expected_re[6] = 8'sb01111111;
    expected_re[7] = 8'sb01111111;

    expected_im[0] = 8'sb00000000;
    expected_im[1] = 8'sb00000000;
    expected_im[2] = 8'sb00000000;
    expected_im[3] = 8'sb00000000;
    expected_im[4] = 8'sb00000000;
    expected_im[5] = 8'sb00000000;
    expected_im[6] = 8'sb00000000;
    expected_im[7] = 8'sb00000000;

    // Reset sequence
    rst = 1;
    x_re = 0;
    x_im = 0;
    #(CLK_PERIOD*2);
    rst = 0;
    #(CLK_PERIOD);

    // Test case 1: Impulse response (all frequency components should be equal)
    x_re = 8'sb01111111; // 1.0
    x_im = 8'sb00000000; // 0.0
    #(CLK_PERIOD);
    x_re = 0;
    x_im = 0;

    // Wait for computation to complete (4 stages + output)
    #(CLK_PERIOD*8);

    // Check outputs
    for (i = 0; i < 8; i = i + 1) begin
        if (y_re !== expected_re[i] || y_im !== expected_im[i]) begin
            $display("Error at output %0d: Input (%0d, %0d), Expected (%0d, %0d), Got (%0d, %0d)", 
                    i, 8'sb01111111, 8'sb00000000, expected_re[i], expected_im[i], y_re, y_im);
            error_count = error_count + 1;
        end
        #(CLK_PERIOD);
    end

    // Test case 2: DC input (all samples 1 + j0)
    expected_re[0] = 8'sb01111111; // DC component
    expected_re[1] = 0;
    expected_re[2] = 0;
    expected_re[3] = 0;
    expected_re[4] = 0;
    expected_re[5] = 0;
    expected_re[6] = 0;
    expected_re[7] = 0;

    expected_im[0] = 0;
    expected_im[1] = 0;
    expected_im[2] = 0;
    expected_im[3] = 0;
    expected_im[4] = 0;
    expected_im[5] = 0;
    expected_im[6] = 0;
    expected_im[7] = 0;

    // Apply DC input
    for (i = 0; i < 8; i = i + 1) begin
        x_re = 8'sb01111111;
        x_im = 8'sb00000000;
        #(CLK_PERIOD);
    end
    x_re = 0;
    x_im = 0;

    // Wait for computation to complete
    #(CLK_PERIOD*8);

    // Check outputs
    for (i = 0; i < 8; i = i + 1) begin
        if (y_re !== expected_re[i] || y_im !== expected_im[i]) begin
            $display("Error at output %0d: Input (%0d, %0d), Expected (%0d, %0d), Got (%0d, %0d)", 
                    i, 8'sb01111111, 8'sb00000000, expected_re[i], expected_im[i], y_re, y_im);
            error_count = error_count + 1;
        end
        #(CLK_PERIOD);
    end

    // Summary
    if (error_count == 0) begin
        $display("No Function Error");
    end else begin
        $display("Exist Function Error");
    end

    $finish;
end

endmodule

`timescale 1ns/1ps

module tb_aes_encrypt_128();
    // Inputs
    reg clk;
    reg rst;
    reg start;
    reg [127:0] p;
    reg [127:0] k;

    // Outputs
    wire [127:0] c;
    wire done;

    // Instantiate the Unit Under Test (UUT)
    aes_encrypt_128 uut (
        .clk(clk),
        .rst(rst),
        .start(start),
        .p(p),
        .k(k),
        .c(c),
        .done(done)
    );

    // Clock generation
    parameter CLK_PERIOD = 10;
    always #(CLK_PERIOD/2) clk = ~clk;

    // Test vectors
    reg [127:0] test_plaintext [0:2];
    reg [127:0] test_key [0:2];
    reg [127:0] expected_ciphertext [0:2];

    integer i, cycle_count, timeout;
    integer error_count = 0;

    initial begin
        // Initialize test vectors
        // Test case 1: NIST FIPS-197 example
        test_plaintext[0] = 128'h00112233445566778899aabbccddeeff;
        test_key[0] = 128'h000102030405060708090a0b0c0d0e0f;
        expected_ciphertext[0] = 128'h69c4e0d86a7b0430d8cdb78070b4c55a;

        // Test case 2: Another test vector
        test_plaintext[1] = 128'h3243f6a8885a308d313198a2e0370734;
        test_key[1] = 128'h2b7e151628aed2a6abf7158809cf4f3c;
        expected_ciphertext[1] = 128'h3925841d02dc09fbdc118597196a0b32;

        // Test case 3: Zero inputs
        test_plaintext[2] = 128'h0;
        test_key[2] = 128'h0;
        expected_ciphertext[2] = 128'h66e94bd4ef8a2c3b884cfa59ca342b2e; // Correct ciphertext for zero inputs

        // Initialize inputs
        clk = 0;
        rst = 1;
        start = 0;
        p = 0;
        k = 0;
        cycle_count = 0;
        timeout = 0;

        // Reset the system
        #(2*CLK_PERIOD);
        rst = 0;
        #(CLK_PERIOD);
        if (c !== 128'b0 || done !== 1'b0) begin
            $display("Reset failed: c = %h, done = %b", c, done);
            error_count = error_count + 1;
        end

        // Run tests
        for (i = 0; i < 3; i = i + 1) begin
            // Load inputs
            p = test_plaintext[i];
            k = test_key[i];
            start = 1;
            cycle_count = 0;
            timeout = 0;

            #(CLK_PERIOD);
            start = 0;

            // Wait for completion or timeout
            while (!done && timeout < 20) begin
                @(posedge clk);
                timeout = timeout + 1;
                cycle_count = cycle_count + 1;
            end

            if (timeout >= 20) begin
                $display("Test %0d failed: Timeout waiting for done", i+1);
                $display("Input plaintext: %h", p);
                $display("Input key: %h", k);
                error_count = error_count + 1;
            end
            else begin
                @(posedge clk); // Check outputs on next clock edge
                if (c !== expected_ciphertext[i]) begin
                    $display("Test %0d failed", i+1);
                    $display("Input plaintext: %h", p);
                    $display("Input key: %h", k);
                    $display("Output ciphertext: %h", c);
                    $display("Expected ciphertext: %h", expected_ciphertext[i]);
                    error_count = error_count + 1;
                end
                if (cycle_count > 10)
                    $display("Test %0d warning: Encryption took %0d cycles, expected <= 10", i+1, cycle_count);
            end

            // Check done persistence
            repeat(5) @(posedge clk) begin
                if (done && !start && !rst)
                    if (!done) begin
                        $display("Test %0d failed: done deasserted prematurely", i+1);
                        error_count = error_count + 1;
                    end
            end

            // Reset for next test
            rst = 1;
            #(CLK_PERIOD);
            rst = 0;
            #(CLK_PERIOD);
        end

        // Final status
        if (error_count == 0)
            $display("No Function Error");
        else
            $display("Exist Function Error");

        $finish;
    end
endmodule

`timescale 1ns/1ps

module tb_sort_asc_4;

// Inputs
reg [3:0] a, b, c, d;

// Outputs
wire [3:0] ra, rb, rc, rd;

// Instantiate the Unit Under Test (UUT)
sort_asc_4 uut (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .ra(ra),
    .rb(rb),
    .rc(rc),
    .rd(rd)
);

integer i;
reg [3:0] expected [0:3];
reg error_flag;
reg [3:0] temp;  // Moved temp declaration to module level

initial begin
    error_flag = 0;

    // Test case 1: Random values
    a = 4'd5; b = 4'd2; c = 4'd7; d = 4'd3;
    expected[0] = 4'd2; expected[1] = 4'd3; expected[2] = 4'd5; expected[3] = 4'd7;
    #10;
    if (ra !== expected[0] || rb !== expected[1] || rc !== expected[2] || rd !== expected[3]) begin
        $display("Error Case 1: Inputs %0d,%0d,%0d,%0d", a, b, c, d);
        $display("Expected: %0d,%0d,%0d,%0d", expected[0], expected[1], expected[2], expected[3]);
        $display("Got: %0d,%0d,%0d,%0d", ra, rb, rc, rd);
        error_flag = 1;
    end

    // Test case 2: Already sorted
    a = 4'd1; b = 4'd2; c = 4'd3; d = 4'd4;
    expected[0] = 4'd1; expected[1] = 4'd2; expected[2] = 4'd3; expected[3] = 4'd4;
    #10;
    if (ra !== expected[0] || rb !== expected[1] || rc !== expected[2] || rd !== expected[3]) begin
        $display("Error Case 2: Inputs %0d,%0d,%0d,%0d", a, b, c, d);
        $display("Expected: %0d,%0d,%0d,%0d", expected[0], expected[1], expected[2], expected[3]);
        $display("Got: %0d,%0d,%0d,%0d", ra, rb, rc, rd);
        error_flag = 1;
    end

    // Test case 3: Reverse order
    a = 4'd9; b = 4'd6; c = 4'd4; d = 4'd1;
    expected[0] = 4'd1; expected[1] = 4'd4; expected[2] = 4'd6; expected[3] = 4'd9;
    #10;
    if (ra !== expected[0] || rb !== expected[1] || rc !== expected[2] || rd !== expected[3]) begin
        $display("Error Case 3: Inputs %0d,%0d,%0d,%0d", a, b, c, d);
        $display("Expected: %0d,%0d,%0d,%0d", expected[0], expected[1], expected[2], expected[3]);
        $display("Got: %0d,%0d,%0d,%0d", ra, rb, rc, rd);
        error_flag = 1;
    end

    // Test case 4: All equal values
    a = 4'd5; b = 4'd5; c = 4'd5; d = 4'd5;
    expected[0] = 4'd5; expected[1] = 4'd5; expected[2] = 4'd5; expected[3] = 4'd5;
    #10;
    if (ra !== expected[0] || rb !== expected[1] || rc !== expected[2] || rd !== expected[3]) begin
        $display("Error Case 4: Inputs %0d,%0d,%0d,%0d", a, b, c, d);
        $display("Expected: %0d,%0d,%0d,%0d", expected[0], expected[1], expected[2], expected[3]);
        $display("Got: %0d,%0d,%0d,%0d", ra, rb, rc, rd);
        error_flag = 1;
    end

    // Test case 5: Random test with 10 iterations
    for (i = 0; i < 10; i = i + 1) begin
        a = $random % 16;
        b = $random % 16;
        c = $random % 16;
        d = $random % 16;

        // Calculate expected output using simple sorting algorithm
        expected[0] = (a <= b && a <= c && a <= d) ? a :
                     (b <= a && b <= c && b <= d) ? b :
                     (c <= a && c <= b && c <= d) ? c : d;
        expected[3] = (a >= b && a >= c && a >= d) ? a :
                     (b >= a && b >= c && b >= d) ? b :
                     (c >= a && c >= b && c >= d) ? c : d;

        // Calculate middle values
        if (a != expected[0] && a != expected[3]) begin
            expected[1] = a;
            if (b != expected[0] && b != expected[3]) expected[2] = b;
            else if (c != expected[0] && c != expected[3]) expected[2] = c;
            else expected[2] = d;
        end
        else if (b != expected[0] && b != expected[3]) begin
            expected[1] = b;
            if (a != expected[0] && a != expected[3]) expected[2] = a;
            else if (c != expected[0] && c != expected[3]) expected[2] = c;
            else expected[2] = d;
        end
        else begin
            expected[1] = c;
            expected[2] = d;
        end

        // Ensure proper ordering of middle values
        if (expected[1] > expected[2]) begin
            temp = expected[1];
            expected[1] = expected[2];
            expected[2] = temp;
        end

        #10;
        if (ra !== expected[0] || rb !== expected[1] || rc !== expected[2] || rd !== expected[3]) begin
            $display("Error Case 5.%0d: Inputs %0d,%0d,%0d,%0d", i, a, b, c, d);
            $display("Expected: %0d,%0d,%0d,%0d", expected[0], expected[1], expected[2], expected[3]);
            $display("Got: %0d,%0d,%0d,%0d", ra, rb, rc, rd);
            error_flag = 1;
        end
    end

    if (error_flag) begin
        $display("Exist Function Error");
    end else begin
        $display("No Function Error");
    end

    $finish;
end

endmodule

