    .clk(clk),
    .we(we),
    .re(re),
    .addr(addr),
    .din(din),
    .dout(dout)
);

// Clock generation
initial begin
    clk = 0;
    forever #5 clk = ~clk;
end

// Test stimulus and verification
initial begin
    // Initialize error_flag
    error_flag = 0;

    // Initialize inputs
    we = 0;
    re = 0;
    addr = 0;
    din = 0;

    // Initialize test_mem
    for (integer i = 0; i < 8; i = i + 1) begin
        test_mem[i] = 8'b0;
    end

    // Wait for global reset
    #10;

    // Test case 1: Write data to all addresses
    for (integer i = 0; i < 8; i = i + 1) begin
        we = 1;
        re = 0;
        addr = i;
        din = $random;
        test_mem[i] = din; // Store written data in test_mem
        #10;
    end
    we = 0;

    // Test case 2: Read back data and verify
    for (integer i = 0; i < 8; i = i + 1) begin
        we = 0;
        re = 1;
        addr = i;
        #10;
