        a = 16'd125;
        b = 16'd30;
        expected = a * b;
        #10; // Allow propagation delay
        run_test_case(1);

        // Test case 2: Negative x Positive
        a = -16'd200;
        b = 16'd50;
        expected = a * b;
        #10;
        run_test_case(2);

        // Test case 3: Positive x Negative
        a = 16'd300;
        b = -16'd40;
        expected = a * b;
        #10;
        run_test_case(3);

        // Test case 4: Negative x Negative
        a = -16'd150;
        b = -16'd25;
        expected = a * b;
        #10;
        run_test_case(4);

        // Test case 5: Zero case
        a = 16'd0;
        b = -16'd32768;
        expected = a * b;
        #10;
        run_test_case(5);

        // Test case 6: Max positive values
        a = 16'd32767;
        b = 16'd32767;
        expected = a * b;
        #10;
        check_overflow(6); // Check for overflow
        run_test_case(6);

        // Test case 7: Min negative values
        a = -16'd32768;
        b = -16'd32768;
        expected = a * b;
        #10;
        check_overflow(7); // Check for overflow
        run_test_case(7);

        // Random test cases with fixed seed for reproducibility
