        begin
            temp = a * b; // Perform multiplication in 32-bit arithmetic
            if ((a[15] == b[15] && temp[31] != 0) || (a[15] != b[15] && temp[31] != 1)) begin
                //$display("Warning: Test case %d may cause overflow", test_num);
            end
        end
    endtask

