            else if (gt !== exp_gt || eq !== exp_eq || lt !== exp_lt) begin
                $display("Error in Test %0d: a=%b, b=%b, gt=%b (exp:%b), eq=%b (exp:%b), lt=%b (exp:%b)",
                         test_num, a, b, gt, exp_gt, eq, exp_eq, lt, exp_lt);
