module tb_cordic_8bit;

// Parameters
parameter CLK_PERIOD = 10; // Clock period in ns
parameter PIPELINE_STAGES = 8; // Assumed pipeline stages for 8-bit precision
parameter TOLERANCE = 1; // Allow ±1 LSB error

// Inputs
