            $display("Error: Up count 2 failed. Input: rst=0, en=1, up_down=1 | Output: %b | Expected: 4'b0010", q);
            error_count = error_count + 1;
        end

        // Test down count
        up_down = 0;
        #10;
        if (q !== 4'b0001) begin
            $display("Error: Down count 1 failed. Input: rst=0, en=1, up_down=0 | Output: %b | Expected: 4'b0001", q);
            error_count = error_count + 1;
        end
