        #10;
        if (q !== 4'b1111) begin
            $display("Error: Down count to min failed. Input: rst=0, en=1, up_down=0 | Output: %b | Expected: 4'b1111", q);
            error_count = error_count + 1;
        end

        // Final check
        if ($time != 360) begin
