    repeat (5) begin
        step = 1;
        #10;
        step = 0;
        #10;
    end
    if (count !== 16'd10000 || goal !== 1'b1) begin
        $display("Error: Test 5 failed. Input: step=%b, rst=%b | Output: count=%d, goal=%b | Expected: count=10000, goal=1", step, rst, count, goal);
        error_flag = 1;
    end

