        // Test case 1: d = 00
        d = 2'b00;
        check_output(2'b00, 4'b0001);

        // Test case 2: d = 01
        d = 2'b01;
        check_output(2'b01, 4'b0010);

        // Test case 3: d = 10
        d = 2'b10;
        check_output(2'b10, 4'b0100);

        // Test case 4: d = 11
        d = 2'b11;
        check_output(2'b11, 4'b1000);

        // Final result
        if (error_flag) begin
            $display("Exist Function Error");
        end else begin
            $display("No Function Error");
        end
        $finish;
    end
endmodule
